import java.util.*;

interface SimpleIterator<T> {
    boolean hasNext();
    T next();
}

interface BookAggregate {
    SimpleIterator<String> iterator();
}

// Concrete aggregate hides ArrayList; client never sees it.
final class Library implements BookAggregate {
    private final List<String> books = new ArrayList<>();
    private int modCount = 0;

    void addBook(String title) {
        books.add(title);
        modCount++;
    }

    @Override
    public SimpleIterator<String> iterator() {
        // Snapshot: consistent view, immune to later adds.
        // Trade-off: O(n) copy at creation for O(1) safe traversal.
        return new SnapshotBookIterator(List.copyOf(books));
    }

    public SimpleIterator<String> liveIterator() {
        return new LiveBookIterator(this);
    }

    private static final class SnapshotBookIterator implements SimpleIterator<String> {
        private final List<String> snapshot;
        private int pos = 0;
        SnapshotBookIterator(List<String> snapshot) { this.snapshot = snapshot; }
        @Override public boolean hasNext() { return pos < snapshot.size(); }
        @Override public String next() {
            if (!hasNext()) throw new NoSuchElementException("exhausted");
            return snapshot.get(pos++);
        }
    }

    // Live view with fail-fast detection.
    private static final class LiveBookIterator implements SimpleIterator<String> {
        private final Library source;
        private final int expectedMod;
        private int pos = 0;
        LiveBookIterator(Library source) {
            this.source = source;
            this.expectedMod = source.modCount;
        }
        private void checkModified() {
            if (expectedMod != source.modCount)
                throw new ConcurrentModificationException("library mutated during traversal");
        }
        @Override public boolean hasNext() { checkModified(); return pos < source.books.size(); }
        @Override public String next() {
            checkModified();
            if (!hasNext()) throw new NoSuchElementException("exhausted");
            return source.books.get(pos++);
        }
    }
}

import java.util.*;

final class TreeNode<T> {
    T value; TreeNode<T> left, right;
    TreeNode(T v) { this.value = v; }
}

// Same tree, two orders, zero changes to TreeNode.
final class DepthFirstIterator<T> implements SimpleIterator<T> {
    private final Deque<TreeNode<T>> stack = new ArrayDeque<>();
    DepthFirstIterator(TreeNode<T> root) { if (root != null) stack.push(root); }
    @Override public boolean hasNext() { return !stack.isEmpty(); }
    @Override public T next() {
        if (!hasNext()) throw new NoSuchElementException("exhausted");
        TreeNode<T> n = stack.pop();
        if (n.right != null) stack.push(n.right);
        if (n.left != null) stack.push(n.left);
        return n.value;
    }
}

final class BreadthFirstIterator<T> implements SimpleIterator<T> {
    private final Queue<TreeNode<T>> queue = new ArrayDeque<>();
    BreadthFirstIterator(TreeNode<T> root) { if (root != null) queue.add(root); }
    @Override public boolean hasNext() { return !queue.isEmpty(); }
    @Override public T next() {
        if (!hasNext()) throw new NoSuchElementException("exhausted");
        TreeNode<T> n = queue.remove();
        if (n.left != null) queue.add(n.left);
        if (n.right != null) queue.add(n.right);
        return n.value;
    }
}
